export interface BlogPost {
  slug: string;
  title: string;
  excerpt: string;
  content: string;
  featuredImage: string;
  category: string;
  author: string;
  publishedAt: string;
  published: boolean;
  metaTitle: string;
  metaDescription: string;
  tags: string[];
  /** If set, the card links here instead of /blog/[slug] (for dedicated landing pages). */
  canonicalPath?: string;
}

export type BlogCtaAudience = "charging" | "distribution" | "neutral";

const DISTRIBUTION_CTA_CATEGORIES = new Set([
  "API", "Automotive", "Distribution", "Distribution Partners", "Fintech", "Fleet",
  "Fleet & Mobility", "Fleet Charging", "Fleets", "Insurance", "OEMs", "Platforms",
  "Retail", "Super Apps",
]);

const CHARGING_CTA_CATEGORIES = new Set([
  "Charge Point Operators", "Charging Partners", "Operations",
]);

export const getBlogCtaAudience = (post: BlogPost): BlogCtaAudience => {
  if (DISTRIBUTION_CTA_CATEGORIES.has(post.category)) return "distribution";
  if (CHARGING_CTA_CATEGORIES.has(post.category)) return "charging";

  const signals = `${post.slug} ${post.title} ${post.tags.join(" ")}`.toLowerCase();
  if (/\b(oem|fleet|fintech|neobank|insurance|wallet|super-app|telematics|parking|hotel|retail|embedded|white-label|in-car|connected-car)\b/.test(signals)) {
    return "distribution";
  }
  if (/\b(cpo|operator|charger-utilisation|charger-downtime|tariff|station-franchise|cash-flow|settlement-timing|treasury)\b/.test(signals)) {
    return "charging";
  }
  return "neutral";
};

// Returns the short keyword title (before the colon) for use in cards and listings
export const getDisplayTitle = (post: BlogPost): string => {
  if (post.title.includes(':')) {
    return post.title.split(':')[0].trim();
  }
  return post.title;
};

// Reading time calculator (words per minute)
export const calculateReadingTime = (content: string): number => {
  const wordsPerMinute = 200;
  const words = content.replace(/<[^>]*>/g, '').split(/\s+/).length;
  return Math.ceil(words / wordsPerMinute);
};

